var rings = [];
var ringsNum = 29;
var R = 200;
var palette = [
  "#F5D7DF",
  "#F6EBE6",
  "#BBF3ED",
  "#F4C4D9",
  "#83D8F3",
  "#C4D7EB",
];

var count = -180;

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  angleMode(DEGREES);
  noStroke();

  R = max(width, height) * 0.35;

  for (let i = 0; i < ringsNum; i++) {
    rings.push(new Ring(i));
  }

  background("#E7ECF2");
}

function draw() {
  if (width > height) {
    translate((width / 2 + R) * sin(count * 0.25), 0);
  } else {
    translate(0, (width / 2 + R) * sin(count * 0.25));
  }

  rotateY(sin(count * 0.5) * 10);
  rotateX(count * 0.5);
  rotateZ(sin(count * 0.5) * 10);

  for (let i = 0; i < rings.length; i++) {
    push();
    rotateY((i * 360) / rings.length);
    rings[i].move();
    rings[i].display();
    pop();
  }

  count++;
}

class Ring {
  constructor(tmpIndex) {
    this.index = tmpIndex;
    this.shapes = [];
    this.shapesNum = 30;

    for (let i = 0; i < this.shapesNum; i++) {
      this.shapes.push(new Shape(this.index, i, this.shapesNum));
    }
  }

  move() {}

  display() {
    for (let i = 0; i < this.shapes.length; i++) {
      this.shapes[i].move();
      this.shapes[i].display();
    }
  }
}

class Shape {
  constructor(tmpRingIndex, tmpIndex, tmpNum) {
    this.ringIndex = tmpRingIndex;
    this.num = tmpNum;
    this.index = tmpIndex;
    this.t = (this.index * 360) / this.num;
    this.x = R * cos(this.t);
    this.y = R * sin(this.t);
    this.c = palette[(this.ringIndex + this.index) % palette.length];
    this.s = 0;
  }

  move() {
    this.s = map(sin(this.ringIndex * 13 + frameCount), -1, 1, 0, 100);
  }

  display() {
    fill(this.c);
    push();
    translate(this.x, this.y);
    rotateY(90 + frameCount + this.index * 17);
    rotateX(frameCount + this.index * 13);
    plane(10, this.s);
    pop();
  }
}
